package com.eva.ro.contab.documente;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.Map;

/**
 * A84 (H11) — NIR 14-3-1A: «Cantitatea conform documente» vine din factură / aviz, iar «Recepționat — Cantitate» e
 * cantitatea găsită de comisie (rubrica «receptionat», câte una pe rând, în ordinea liniilor; implicit cea din
 * document). Pe fiecare linie: {@code receptionat}, {@code dif} (recepționat − document), {@code valoare_rec};
 * totalul recepționat; dacă există diferențe și rubrica «Diferențe constatate» e goală, se completează singură
 * («cod denumire: +/−cantitate U/M (valoare)») — OMFP 2634/2015 anexa 2: NIR-ul se întocmește și la diferențe.
 */
public final class NirReceptie {

    private NirReceptie() {
    }

    @SuppressWarnings("unchecked")
    public static void calculeaza(Map<String, Object> model, Map<String, Object> emitere) {
        Object b = model.get("bunuri");
        if (!(b instanceof List))
            return;
        List<Map<String, Object>> bunuri = (List<Map<String, Object>>) b;
        String[] rec = String.valueOf(emitere.getOrDefault("receptionat", "")).split("\\r?\\n");
        BigDecimal total = BigDecimal.ZERO, valDif = BigDecimal.ZERO;
        StringBuilder dif = new StringBuilder();
        int k = 0;
        for (Map<String, Object> l : bunuri) {
            BigDecimal cant = l.get("cant") instanceof BigDecimal ? (BigDecimal) l.get("cant") : BigDecimal.ZERO;
            BigDecimal pret = l.get("pret") instanceof BigDecimal ? (BigDecimal) l.get("pret") : BigDecimal.ZERO;
            BigDecimal r = null;
            while (k < rec.length && r == null) {
                String t = rec[k++].trim();
                if (!t.isEmpty())
                    r = FormatRO.numar(t);
            }
            if (r == null)
                r = cant;
            BigDecimal d = r.subtract(cant);
            BigDecimal v = r.multiply(pret).setScale(2, RoundingMode.HALF_UP);
            l.put("receptionat", r);
            l.put("dif", d);
            l.put("valoare_rec", v);
            total = total.add(v);
            if (d.signum() != 0) {
                BigDecimal vd = d.multiply(pret).setScale(2, RoundingMode.HALF_UP);
                valDif = valDif.add(vd);
                dif.append(dif.length() > 0 ? "\n" : "").append(l.getOrDefault("cod", "")).append(' ')
                   .append(l.getOrDefault("denumire", "")).append(": ").append(d.signum() > 0 ? "+" : "")
                   .append(FormatRO.cant(d)).append(' ').append(l.getOrDefault("um", "")).append(" (")
                   .append(FormatRO.suma(vd)).append(" lei)");
            }
        }
        model.put("total_receptionat", total);
        if (dif.length() > 0) {
            Object e = emitere.get("diferente");
            if (e == null || String.valueOf(e).trim().isEmpty())
                emitere.put("diferente", dif.toString());
            Object vd = emitere.get("valoare_diferente");
            if (vd == null || String.valueOf(vd).trim().isEmpty())
                emitere.put("valoare_diferente", FormatRO.suma(valDif));
        }
    }
}
