package com.eva.ro.saga.table;

import com.eva.ro.saga.core.ColumnMap;
import com.eva.ro.saga.core.InvoiceHeaderImporter;
import com.eva.ro.saga.core.Layer;
import com.eva.ro.saga.core.Rule;
import com.eva.ro.saga.core.SagaTable;
import com.eva.ro.saga.core.Target;

/**
 * INTRARI (antet de factură de achiziție) → C_Invoice.
 *
 * Nu stagează: validează antetul și îl depune în cache-ul de antete, de unde îl ia
 * Intrari → INTR_DET. Aceasta e ordinea impusă de {@code Import_Invoice},
 * care consumă un rând per LINIE, cu antetul repetat.
 *
 * Un TOTAL negativ marchează stornarea: documentul devine notă de credit
 * (APC) cu valori absolute.
 *
 * <h3>Antetul nevalidat intră în CIORNĂ, nu se mai sare (P5, 07.09.2026)</h3>
 * INTRARI era singura dintre cele patru surse care CITEA marcajul {@code VALIDAT} — dar îl
 * folosea ca să SARĂ antetul de tot. Justificarea era bună pe jumătate: SAGA nu scrie nicio
 * notă în REGISTRU pentru un antet nevalidat, deci importat ca document FINALIZAT ar fi umflat
 * 371/6xx și 401 cu sume pe care sursa nu le recunoaște (verificat pe 3D SPACE: 4 antete,
 * 10.781,10 lei, niciunul cu rând în REGISTRU). Se pierdea însă documentul cu totul: la
 * CAFENEA, 8 din 9 intrări nevalidate erau lăsate afară „corect", dar contabilul nu le mai
 * găsea nicăieri ca să le termine.
 *
 * <p>Regula e acum comună celor patru surse și stă într-un singur loc,
 * {@code InvoiceHeaderImporter}: nevalidatul se importă în CIORNĂ — are toate datele, se vede
 * în ecrane, n-are niciun efect contabil. Se acceptă {@code 'V'} și {@code 'l'}, ca și până
 * acum. De aceea clasa asta nu mai suprascrie nimic.
 */
@SagaTable(name = "INTRARI", step = 39, layer = Layer.L8_FACTURI,
           target = Target.NATIVE_PROCESS, process = "Import_Invoice",
           idempiereTable = "C_Invoice", referenceRows = 1358)
public class IntrariImporter extends InvoiceHeaderImporter {

    @Override
    protected void declareColumns(ColumnMap m) {
        m.map("ID_INTRARE", "C_Invoice.DocumentNo", Rule.PARENT_KEY);
        m.map("NR_NIR", "C_Invoice.EVA_NrNir");   // P01.T200 (spec §7): păstrat de aplicaAtribute
        m.map("NR_INTRARE", "C_Invoice.POReference");
        m.map("COD", "C_Invoice.C_BPartner_ID", Rule.PREFIX_CLIENT);
        m.map("DENUMIRE", "C_Invoice.Description");
        m.derive("TVAI", "TVA la încasare (art. 282 CF) → exigibilitate; păstrat în descriere");
        m.map("DATA", "C_Invoice.DateAcct", Rule.DATE);   // luna jurnalului de TVA (exigibilitatea)
        m.map("SCADENT", "C_Invoice.DueDate", Rule.DATE);
        m.derive("NEACHITAT", "soldul neachitat → rezultă din alocările de plăți (stratul L9), nu se importă ca atribut");
        m.map("BAZA_TVA", "C_Invoice.TotalLines", Rule.NUMBER);
        m.derive("TRANSP_LEI", "transport în lei → linie separată pe contul de transport");
        m.map("TVA", "C_InvoiceTax.TaxAmt", Rule.NUMBER);
        m.map("TOTAL", "C_Invoice.GrandTotal", Rule.NUMBER);
        m.map("VALIDAT", "C_Invoice.DocStatus (V/l = finalizat+postat; altfel CIORNĂ,"
            + " nepostată, marcată «nevalidat în SAGA»)");
        m.map("CONT_FUR", "C_Invoice.C_BPartner_ID", Rule.PREFIX_CLIENT);
        m.derive("TIP", "tipul documentului SAGA → determină DocBaseType; păstrat în descriere");
