    /** Unitarele straturilor liniilor documentului afișat (o interogare pe document). */
    private java.util.Map<Integer, java.math.BigDecimal> unitareStrat = new java.util.HashMap<>();
    private int unitareFactura;

    @Override protected void decoreazaCelulaLinie(org.adempiere.webui.component.ListCell cc, int coloana, String cheieColoana,
            int cInvoiceLineId) {
        if (!"col.cost_unit_cu_chelt".equals(cheieColoana))
            return;
        int client = org.compiere.util.Env.getAD_Client_ID(org.compiere.util.Env.getCtx());
        if (!com.eva.ro.contab.fiscal.MotorStraturi.activ(client))
            return;
        int factura = org.compiere.util.DB.getSQLValueEx(null,
                "SELECT C_Invoice_ID FROM C_InvoiceLine WHERE C_InvoiceLine_ID=? AND AD_Client_ID=?", cInvoiceLineId, client);
        if (factura != unitareFactura) {
            unitareStrat = com.eva.ro.contab.fiscal.MotorStraturi.unitareStratFactura(client, factura, null);
            unitareFactura = factura;
        }
        java.math.BigDecimal strat = unitareStrat.get(cInvoiceLineId);
        String t = cc.getLabel() == null ? "" : cc.getLabel().replaceAll("[^0-9.\\-]", "");
        java.math.BigDecimal afisat = t.isEmpty() ? null : new java.math.BigDecimal(t);
        if (com.eva.ro.contab.fiscal.ImpartireAccesoriu.diferaCelula(afisat, strat)) {
            cc.setSclass((cc.getSclass() == null ? "" : cc.getSclass() + " ") + "eva-st-rosu");
            cc.setTooltiptext(com.eva.ro.contab.documente.Etichete.t("landed.cost.diferit", bani(afisat), bani(strat)));
        }
    }
