    /** Semnele «?», în ordine, înlocuite cu literalii parametrilor (Integer ⇒ număr, altfel text dolar-citat). */
    static String sub(String sql, Object... p) {
        StringBuilder o = new StringBuilder();
        int k = 0;
        for (char c : sql.toCharArray()) {
            if (c != '?') {
                o.append(c);
                continue;
            }
            Object v = p[k++];
            o.append(v instanceof Integer ? String.valueOf(v) : "$q$" + v + "$q$");
        }
        if (k != p.length)
            throw new IllegalStateException("parametri: " + k + " semne, " + p.length + " valori");
        return o.toString();
    }

