    /**
     * D7-2: de ce NU se poate confirma o asociere (cheia etichetei), sau null. Refuz: direcția nu e P / T; rândul e deja
     * legat de altă factură EvA; rândul e «Sigur» / «Confirmat» (inclusiv factura trimisă din EvA, legată la încărcare —
     * schimbarea ei ar lăsa factura inițială fără rând, iar «Trimit» ar re-încoada-o și ar re-trimite-o la ANAF).
     */
    public static String refuzConfirmare(String directie, String asociere, int invoiceLegat, int invoiceNou) {
        if (!"P".equals(directie) && !"T".equals(directie))
            return "efactura.asoc.doar_facturi";
        if (invoiceLegat > 0 && invoiceLegat != invoiceNou)
            return "efactura.asoc.rand_legat";
        if (SIGUR.equals(asociere) || CONFIRMAT.equals(asociere))
            return "efactura.asoc.rand_legat";
        return null;
    }

    /**
     * B-1 (P01.T224, D-A3-1 / G-05): regula confirmării din ecran, când factura vine aleasă SAU propusă ({@code invoicePropus} = factura aleasă
     * de om, altfel {@code AsocPropusa}, altfel 0 / -1). Ordinea: întâi {@link #refuzConfirmare} (un rând deja legat / «Sigur» / «Confirmat» dă
     * {@code rand_legat} chiar fără factură propusă — după o confirmare {@code AsocPropusa} e null), apoi «nicio factură» ({@code <= 0}) dă
     * {@code fara_propunere}; altfel null. Singurul loc al deciziei (ecranul cheamă mereu {@link #confirma}).
     */
    public static String refuzConfirmareFaraFactura(String directie, String asociere, int invoiceLegat, int invoicePropus) {
        String refuz = refuzConfirmare(directie, asociere, invoiceLegat, invoicePropus);
        if (refuz != null)
            return refuz;
        return invoicePropus <= 0 ? "efactura.asoc.fara_propunere" : null;
    }

    /** D7-2: de ce NU se poate respinge (cheia etichetei), sau null: rândul e deja legat (C_Invoice_ID, Sigur, Confirmat). */
    public static String refuzRespingere(String directie, String asociere, int invoiceLegat) {
        if (!"P".equals(directie) && !"T".equals(directie))
            return "efactura.asoc.doar_facturi";
        if (invoiceLegat > 0 || SIGUR.equals(asociere) || CONFIRMAT.equals(asociere))
            return "efactura.asoc.rand_legat";
        return null;
    }

    /**
