     * nelegat — {@link #refuzConfirmare}, aceeași direcție, factura EvA nelegată de alt mesaj; fără factură — {@code invoiceId <= 0} —
     * {@code fara_propunere}, prin {@link #refuzConfirmareFaraFactura}, B-1 P01.T224). Întoarce null la reușită, altfel motivul (text din etichete).
     */
    public static String confirma(Properties ctx, int clientId, int eFacturaId, int invoiceId, String trx) {
        PO p = MTable.get(ctx, EFacturaCoada.TABELA).getPO(eFacturaId, trx);
        if (p == null || p.get_ID() <= 0 || p.get_ValueAsInt("AD_Client_ID") != clientId)
            return Etichete.t("efactura.asoc.alta_firma");
        String refuz = refuzConfirmareFaraFactura(p.get_ValueAsString("Directie"), p.get_ValueAsString("Asociere"),
                p.get_ValueAsInt("C_Invoice_ID"), invoiceId);
        if (refuz != null)
            return Etichete.t(refuz);
        String soTrx = DB.getSQLValueString(trx, "SELECT issotrx FROM c_invoice WHERE c_invoice_id=? AND ad_client_id=?"
                + " AND docstatus IN ('CO','CL')", invoiceId, clientId);
        if (soTrx == null)
            return Etichete.t("efactura.asoc.alta_firma");
        if (!soTrx.equals("T".equals(p.get_ValueAsString("Directie")) ? "Y" : "N"))
            return Etichete.t("efactura.asoc.alta_directie");
        int alt = DB.getSQLValue(trx, "SELECT eva_efactura_id FROM eva_efactura WHERE ad_client_id=? AND c_invoice_id=?"
                + " AND eva_efactura_id<>? ORDER BY eva_efactura_id LIMIT 1", clientId, invoiceId, eFacturaId);
        if (alt > 0)
            return Etichete.t("efactura.asoc.deja_legata", alt);
        p.set_ValueOfColumn("C_Invoice_ID", invoiceId);
        p.set_ValueOfColumn("AsocPropusa", null);
        p.set_ValueOfColumn("Asociere", CONFIRMAT);
        p.set_ValueOfColumn("AsocDetalii", taie(Etichete.t("efactura.asoc.confirmata"), 255));
        p.saveEx();
        return null;
    }

    /** Omul respinge propunerea: rândul rămâne nelegat și nu se mai propune automat (apare în raportul neasociatelor). */
    public static String respinge(Properties ctx, int clientId, int eFacturaId, String trx) {
        PO p = MTable.get(ctx, EFacturaCoada.TABELA).getPO(eFacturaId, trx);
        if (p == null || p.get_ID() <= 0 || p.get_ValueAsInt("AD_Client_ID") != clientId)
            return Etichete.t("efactura.asoc.alta_firma");
        String refuz = refuzRespingere(p.get_ValueAsString("Directie"), p.get_ValueAsString("Asociere"),
                p.get_ValueAsInt("C_Invoice_ID"));
        if (refuz != null)
            return Etichete.t(refuz);
        p.set_ValueOfColumn("AsocPropusa", null);
        p.set_ValueOfColumn("Asociere", RESPINS);
        p.set_ValueOfColumn("AsocDetalii", taie(Etichete.t("efactura.asoc.respinsa"), 255));
