            + " AND UPPER(COALESCE(q.tipmesaj,'')) IN ('FACTURA PRIMITA','FACTURA TRIMISA') AND COALESCE(q.calearhiva,'')<>''"
            + " AND COALESCE(q.c_invoice_id,0)=0 AND COALESCE(q.datafactura, q.datapublicare) BETWEEN ? AND ?"
            + " ORDER BY 5, 1";

    private static final String SQL_EVA_FARA_SPV = "SELECT i.c_invoice_id, CASE WHEN i.issotrx='Y' THEN 'T' ELSE 'P' END,"
            + " COALESCE(bp.taxid,''), COALESCE(NULLIF(i.poreference,''), i.documentno), i.dateinvoiced, i.grandtotal,"
