    static String constantaDinClasa(String clasa, String camp) throws Exception {
        try (java.io.InputStream in = TestT224IdSpvSql.class.getClassLoader().getResourceAsStream(clasa.replace('.', '/') + ".class")) {
            if (in == null)
                throw new IllegalStateException("clasa lipsă din jar: " + clasa);
            java.io.DataInputStream d = new java.io.DataInputStream(new java.io.BufferedInputStream(in));
            d.readInt();
            d.readUnsignedShort();
            d.readUnsignedShort();
            int n = d.readUnsignedShort();
            String[] utf = new String[n];
            int[] str = new int[n];
            for (int i = 1; i < n; i++) {
                int tag = d.readUnsignedByte();
                switch (tag) {
                    case 1 -> utf[i] = d.readUTF();
                    case 8 -> str[i] = d.readUnsignedShort();
                    case 7, 16, 19, 20 -> d.readUnsignedShort();
                    case 15 -> { d.readUnsignedByte(); d.readUnsignedShort(); }
                    case 3, 4, 9, 10, 11, 12, 17, 18 -> d.readInt();
                    case 5, 6 -> { d.readLong(); i++; }
                    default -> throw new IllegalStateException("etichetă necunoscută în constant pool: " + tag);
                }
            }
            d.readUnsignedShort();
            d.readUnsignedShort();
            d.readUnsignedShort();
            int ni = d.readUnsignedShort();
            for (int i = 0; i < ni; i++)
                d.readUnsignedShort();
            int nf = d.readUnsignedShort();
            for (int f = 0; f < nf; f++) {
                d.readUnsignedShort();
                String nume = utf[d.readUnsignedShort()];
                d.readUnsignedShort();
                int na = d.readUnsignedShort();
                for (int k = 0; k < na; k++) {
                    String an = utf[d.readUnsignedShort()];
                    int len = d.readInt();
                    if (camp.equals(nume) && "ConstantValue".equals(an) && len == 2)
                        return utf[str[d.readUnsignedShort()]];
                    d.skipNBytes(len);
                }
            }
            throw new IllegalStateException("câmpul " + camp + " fără ConstantValue în " + clasa);
        }
    }

