    /** Semnele «?», în ordine, înlocuite cu literalii parametrilor (Integer ⇒ număr, altfel text dolar-citat). */
    static String sub(String sql, Object... p) {
        StringBuilder o = new StringBuilder();
        int k = 0;
        for (char c : sql.toCharArray()) {
            if (c != '?') {
                o.append(c);
                continue;
            }
            Object v = p[k++];
            o.append(v instanceof Integer ? String.valueOf(v) : "$q$" + v + "$q$");
        }
        if (k != p.length)
            throw new IllegalStateException("parametri: " + k + " semne, " + p.length + " valori");
        return o.toString();
    }

    static void chk(String m, String q, String asteptat) {
        nChk++;
        s.append("SELECT CASE WHEN COALESCE((").append(q).append(")::text,'null') = $e$").append(asteptat)
         .append("$e$ THEN 'OK   ' ELSE 'FAIL ' END || $m$").append(m).append("$m$ || ' → ' || COALESCE((").append(q).append(")::text,'null');\n");
    }

    static String mut(String sql, String din, String in) {
        int i = sql.indexOf(din);
        if (i < 0 || sql.indexOf(din, i + 1) >= 0)
            throw new IllegalStateException("ancora mutantului lipsește sau e multiplă: " + din);
        return sql.replace(din, in);
    }

